var _dashboardExtensionUri = null;
function _loadWebviewAsset(name) {
  if (!_dashboardExtensionUri) return "";
  try {
    const p = path2.join(_dashboardExtensionUri.fsPath, "assets", "webview", name);
    return fs.readFileSync(p, "utf-8");
  } catch (e) {
    console.warn(`[Connect AI] webview asset \uB85C\uB4DC \uC2E4\uD328 ${name}:`, e?.message || e);
    return "";
  }
}
